import re
from os.path import join

import requests
from taf.rfrl.utilities.file_downloader import SVNDownloader, URLConnection
from taf.rfrl.utilities.settings import WFT_API_ADR, WFT_ACCESS_KEY, SVN_LOGIN, SVN_PASSWORD, CRACOW_PROXY


class WftUrlBuilder:

    def __init__(self, wft_adr=WFT_API_ADR, access_key=WFT_ACCESS_KEY):
        self.adr = wft_adr
        self.access_key = access_key

    @staticmethod
    def get_views_from_wft_url(url):
        """
        go to the https://wft.int.net.nokia.com/builds?project_filters=ALL, personalize and paste url into this function
        to get the views that can be used in api url
        """
        url = url.replace("%5B", "[").replace("%5D", "]")
        return "&" + "&".join([attr for attr in url.split("&")
                               if "view" in attr and "wft" not in attr and attr[-1] != "="])

    def get_base_api_url(self):
        return "{url}build_branch.json?access_key={akey}".format(url=self.adr, akey=self.access_key)

    @staticmethod
    def add_items_count_to_api_url(url, items_count):
        return url + "&view[items]={items}".format(items=items_count)

    @staticmethod
    def add_filter_to_api_url(url, column, operation, value, column_id=1):
        return url + "&view[view_filters_attributes[{column_id}]][column]={column}" \
                     "&view[view_filters_attributes[{column_id}]][operation]={operation}" \
                     "&view[view_filters_attributes[{column_id}]][value][]={value}".format(column=column, value=value,
                                                                                           operation=operation,
                                                                                           column_id=column_id)

    @staticmethod
    def add_sorting_to_api_url(url, column, direction):
        return url + "&view[sorting_field]={column}" \
                     "&view[sorting_direction]={direction}".format(column=column, direction=direction)

    @staticmethod
    def add_column_to_api_url(url, column):
        return url + "&view[columns[][id]]={column}".format(column=column)

    @staticmethod
    def add_build_artifacts_view_to_api_url(url):
        return WftUrlBuilder.add_column_to_api_url(url, "build_artifacts")

    @staticmethod
    def add_peg_revisions_view_to_api_url(url):
        return WftUrlBuilder.add_column_to_api_url(url, "peg_revisions")


class WftApi:

    def __init__(self, wft_adr=WFT_API_ADR, access_key=WFT_ACCESS_KEY):
        self.WftUrlBuilder = WftUrlBuilder(wft_adr, access_key)
        self.adr = wft_adr
        self.access_key = access_key

    @staticmethod
    def get_peg_revisions_from_content(content):
        return [revision["peg_revision"] for revision in content]

    @staticmethod
    def get_sub_builds_from_content(content, sub_builds):
        return {sub_build["name"]: sub_build["baseline"]
                for sub_build in content if sub_build["name"] in sub_builds}

    @staticmethod
    def get_urls_from_build_aritificats(build_artifacts, banned_titles=None, banned_desc=None):
        banned_titles = ["Can't find the artifacts?"] if banned_titles is None else banned_titles
        banned_desc = ["Click me"] if banned_desc is None else banned_desc
        return {artifact["title"]: artifact["url"]
                for artifact in build_artifacts
                if artifact["title"] not in banned_titles and artifact["description"] not in banned_desc}

    def get_column_from_build_version(self, build_version, column):
        base_url = self.WftUrlBuilder.get_base_api_url()
        base_url = self.WftUrlBuilder.add_filter_to_api_url(base_url, "version", "eq", build_version)
        base_url = self.WftUrlBuilder.add_column_to_api_url(base_url, column)
        api_content = self._check_response_and_get_content(requests.get(base_url))
        return api_content[0][column]

    def get_peg_revisions_from_build_version(self, build_version):
        return self.get_peg_revisions_from_content(self.get_column_from_build_version(build_version, "peg_revisions"))

    def get_url_aritificats_from_build_version(self, build_version, banned_titles=None, banned_desc=None):
        column = self.get_column_from_build_version(build_version, "build_artifacts")
        return self.get_urls_from_build_aritificats(column, banned_titles, banned_desc)

    def get_sub_builds_from_build_version(self, build_version, sub_builds):
        column = self.get_column_from_build_version(build_version, "sub_builds")
        return self.get_sub_builds_from_content(column, sub_builds)

    def get_newest_builds(self, filter_name, filter_value, items_count=50, views=None, released=True,
                          released_with_rest=True):
        views = ["version"] if views is None else views
        base_url = self.WftUrlBuilder.get_base_api_url()
        base_url = self.WftUrlBuilder.add_items_count_to_api_url(base_url, items_count)
        base_url = self.WftUrlBuilder.add_filter_to_api_url(base_url, filter_name, "eq", filter_value, column_id=1)
        base_url = self.WftUrlBuilder.add_sorting_to_api_url(base_url, "created_at", "DESC")
        if released:
            base_url = self.WftUrlBuilder.add_filter_to_api_url(base_url, "state", "eq", "RELEASED", column_id=2)
        if released_with_rest:
            base_url = self.WftUrlBuilder.add_filter_to_api_url(base_url, "state", "eq", "RELEASED_WITH_RESTRICTIONS",
                                                                column_id=3)
        for view in views:
            base_url = self.WftUrlBuilder.add_column_to_api_url(base_url, view)
        return self._check_response_and_get_content(requests.get(base_url))

    def get_newest_builds_by_branch_title(self, branch_title, items_count=50, views=None, released=True,
                                          released_with_rest=True):
        return self.get_newest_builds("branch.title", branch_title, items_count, views, released, released_with_rest)

    def download_file_from_build_aritificats(self, build_version, file_name, repo_title=None, banned_titles=None,
                                             banned_desc=None, file_path="/tmp/", new_file_name=None,
                                             SVN_LOGIN=SVN_LOGIN, SVN_PASSWORD=SVN_PASSWORD,
                                             svne_proxy=CRACOW_PROXY):
        artf = self.get_url_aritificats_from_build_version(build_version, banned_titles, banned_desc)
        artf_titles = artf.keys()
        if repo_title is None or repo_title not in artf.keys():
            repo_title = list(artf_titles)[0]
        url = artf[repo_title]
        if not url.endswith('/'):
            url += "/"
        if "artifactory" in url:
            new_file_name = new_file_name or file_name
            URLConnection().download_file(url + file_name, file_path, new_file_name)
            return join(file_path, new_file_name)
        elif "svne" in url:
            svne = SVNDownloader(https_proxies=svne_proxy, login=SVN_LOGIN, password=SVN_PASSWORD)
            svne_file_tree = svne.get_file_tree(url)
            files = svne.find_files_in_tree(svne_file_tree, file_name)
            file_name = files[0].split("/")[-1] if new_file_name is None else new_file_name
            svne.download_file(files[0], file_path, file_name)
            return join(file_path, file_name)

    def get_content_from_views(self, views):
        return self._check_response_and_get_content(requests.get(self.WftUrlBuilder.get_base_api_url() + views))

    @staticmethod
    def _check_response_and_get_content(resp):
        if not resp.ok:
            msg = (
                'endpoint returned bad response: '
                '"({response.status_code}) {response.reason}".'
            )
            msg = msg.format(response=resp)
            raise WftApiError(msg)
        content = resp.json()
        if content["count"] == 0:
            raise WftApiError("No results found")
        return content["items"]


class WftHubApi(WftApi):

    def __init__(self, hub_versions=None, wft_addr=WFT_API_ADR, access_key=WFT_ACCESS_KEY):
        super(WftHubApi, self).__init__(wft_addr, access_key)
        self.hub_versions = ["ASIHUB", "ASIHUB2.0"] if hub_versions is None else hub_versions
        self.hub_sw_file_regex = r"fzhub\d?-bundle_\d+\.tgz"
        self.rfsw_file_regex = r"RFSW.txz"

    def get_hub_sw_from_sub_builds(self, sub_builds):
        return {sub_build["name"]: sub_build["baseline"]
                for sub_build in sub_builds if sub_build["name"] in self.hub_versions}

    def get_newest_hub_sw_from_sbts_branch_title(self, branch_title="SBTS00", released=True, released_with_rest=True):
        newest_builds = self.get_newest_builds_by_branch_title(branch_title, 1, ["sub_builds"], released,
                                                               released_with_rest)
        return self.get_sub_builds_from_content(newest_builds[0]["sub_builds"], self.hub_versions)

    def get_hub_sw_from_sbts_build_version(self, build_version):
        sub_builds = self.get_column_from_build_version(build_version, "sub_builds")
        return self.get_sub_builds_from_content(sub_builds, self.hub_versions)

    def get_rfsw_from_sub_builds(self, sub_builds):
        return self.get_sub_builds_from_content(sub_builds, ["ASIR_HUB_RFSW"])["ASIR_HUB_RFSW"]

    def get_newest_rfsw_from_sbts_branch_title(self, branch_title="SBTS00", released=True, released_with_rest=True):
        hub_sw = self.get_newest_hub_sw_from_sbts_branch_title(branch_title, released, released_with_rest)
        return {version: self.get_rfsw_from_sub_builds(self.get_column_from_build_version(sw, "sub_builds"))
                for version, sw in hub_sw.items()}

    def get_rfsw_from_sbts_build_version(self, build_version):
        hub_sw = self.get_hub_sw_from_sbts_build_version(build_version)
        return {version: self.get_rfsw_from_sub_builds(self.get_column_from_build_version(sw, "sub_builds"))
                for version, sw in hub_sw.items()}

    def get_newest_sbts_fpga_versions(self, branch_title="SBTS00", released=True, released_with_rest=True):
        rfsw = self.get_newest_rfsw_from_sbts_branch_title(branch_title, released, released_with_rest)
        return {version: self.assign_fpga_image_to_version(self.get_peg_revisions_from_build_version(sw))
                for version, sw in rfsw.items()}

    def get_fpga_versions_from_sbts_build_version(self, build_version):
        rfsw = self.get_rfsw_from_sbts_build_version(build_version)
        return {version: self.assign_fpga_image_to_version(self.get_peg_revisions_from_build_version(sw))
                for version, sw in rfsw.items()}

    def download_hub_sw_from_sbts_build_version(self, build_version, hub_version, file_path="/tmp/", new_file_name=None,
                                                login=SVN_LOGIN, password=SVN_PASSWORD, proxy=CRACOW_PROXY):
        hub_sw = self.get_hub_sw_from_sbts_build_version(build_version)
        return self.download_file_from_build_aritificats(build_version=hub_sw[hub_version], new_file_name=new_file_name,
                                                         file_name=self.hub_sw_file_regex, file_path=file_path,
                                                         SVN_LOGIN=login, SVN_PASSWORD=password, svne_proxy=proxy)

    def download_rfsw_from_sbts_build_version(self, build_version, hub_version, file_path="/tmp/", new_file_name=None,
                                              login=SVN_LOGIN, password=SVN_PASSWORD, proxy=CRACOW_PROXY):
        rfsw = self.get_rfsw_from_sbts_build_version(build_version)
        return self.download_file_from_build_aritificats(build_version=rfsw[hub_version], new_file_name=new_file_name,
                                                         file_name=self.rfsw_file_regex, file_path=file_path,
                                                         SVN_LOGIN=login, SVN_PASSWORD=password, svne_proxy=proxy)

    @staticmethod
    def assign_fpga_image_to_version(fpga_images):
        version = {}
        for image in fpga_images:
            match = re.search(r"\w*?(\d{3})_", image).group(1)
            if match == "514":
                version["gen1"] = image
            elif match == "515":
                version["gen2"] = image
            elif match == "516":
                version["gen3"] = image
        return version


class WftApiError(Exception):
    """ WftApiError Raised when any error occurred. """
